import React, { useState } from "react";
import { useDropzone } from "react-dropzone";
import { ScanFace, Upload, X, CheckCircle, AlertTriangle, ChevronRight, Info, RotateCcw } from "lucide-react";
import toast from "react-hot-toast";
import ScoreRing from "../components/ui/ScoreRing";
import { postureService } from "../services/postureService";

const ANGLES = [
  { key: "front", label: "Front View", hint: "Face the camera, arms at sides" },
  { key: "back",  label: "Back View",  hint: "Turn 180°, look straight ahead" },
  { key: "left",  label: "Left Side",  hint: "Left shoulder toward camera" },
  { key: "right", label: "Right Side", hint: "Right shoulder toward camera" },
];

const METRIC_LABELS = {
  shoulder_tilt_deg:     { label: "Shoulder Tilt",       unit: "°", invert: true },
  hip_tilt_deg:          { label: "Hip Tilt",            unit: "°", invert: true },
  spine_lateral_dev_deg: { label: "Spine Lateral Dev.",  unit: "°", invert: true },
  head_forward_deg:      { label: "Head Forward",        unit: "°", invert: true },
  torso_lean_deg:        { label: "Torso Lean",          unit: "°", invert: true },
};

function AngleSlot({ angle, file, onDrop, onClear, result, loading }) {
  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop: (accepted) => accepted[0] && onDrop(angle.key, accepted[0]),
    accept: { "image/jpeg": [], "image/png": [], "image/webp": [] },
    multiple: false,
  });

  return (
    <div className="card p-4 flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-semibold text-text-primary">{angle.label}</p>
          <p className="text-xs text-text-muted">{angle.hint}</p>
        </div>
        {result && <ScoreRing score={result.posture_score} size={52} strokeWidth={5} />}
      </div>

      {!file ? (
        <div {...getRootProps()} className={`flex flex-col items-center justify-center gap-2 border-2 border-dashed rounded-xl p-6 cursor-pointer transition-colors ${isDragActive ? "border-primary bg-primary/5" : "border-border hover:border-primary/50 hover:bg-primary/5"}`}>
          <input {...getInputProps()} />
          <Upload size={22} className="text-text-muted" />
          <p className="text-xs text-text-secondary text-center">Click or drag photo</p>
        </div>
      ) : (
        <div className="relative rounded-xl overflow-hidden bg-surface">
          <img src={URL.createObjectURL(file)} alt={angle.label} className="w-full h-36 object-cover" />
          {loading && <div className="absolute inset-0 flex items-center justify-center bg-base/60"><div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div></div>}
          <button onClick={() => onClear(angle.key)} className="absolute top-2 right-2 w-6 h-6 rounded-full bg-base/80 flex items-center justify-center text-text-secondary hover:text-danger"><X size={12} /></button>
        </div>
      )}

      {result && (
        <div className="space-y-1.5 pt-1">
          {Object.entries(result.metrics || {}).map(([key, val]) => {
            if (val == null || !METRIC_LABELS[key]) return null;
            const meta = METRIC_LABELS[key];
            const abs = Math.abs(val);
            const good = abs < 5;
            return (
              <div key={key} className="flex items-center justify-between text-xs">
                <span className="text-text-secondary">{meta.label}</span>
                <span className={`font-medium ${good ? "text-accent" : abs > 10 ? "text-danger" : "text-warning"}`}>{val.toFixed(1)}{meta.unit}</span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default function PostureStudio() {
  const [photos, setPhotos] = useState({});
  const [results, setResults] = useState({});
  const [loading, setLoading] = useState({});
  const [overallScore, setOverallScore] = useState(null);

  const handleDrop = (angle, file) => {
    setPhotos((p) => ({ ...p, [angle]: file }));
    setResults((r) => ({ ...r, [angle]: null }));
  };

  const handleClear = (angle) => {
    setPhotos((p) => { const n = { ...p }; delete n[angle]; return n; });
    setResults((r) => { const n = { ...r }; delete n[angle]; return n; });
  };

  const analyzeAll = async () => {
    const toAnalyze = Object.entries(photos).filter(([, f]) => f);
    if (!toAnalyze.length) { toast.error("Upload at least one photo first."); return; }

    let total = 0, wSum = 0;
    const weights = { front: 0.4, back: 0.25, left: 0.2, right: 0.15 };

    for (const [angle, file] of toAnalyze) {
      setLoading((l) => ({ ...l, [angle]: true }));
      try {
        const data = await postureService.analyzeSingle(file, angle);
        setResults((r) => ({ ...r, [angle]: data }));
        if (data?.posture_score != null && weights[angle]) {
          total += data.posture_score * weights[angle];
          wSum  += weights[angle];
        }
        toast.success(`${angle} view analyzed!`);
      } catch (err) {
        toast.error(`${angle}: ${err.message}`);
      } finally {
        setLoading((l) => ({ ...l, [angle]: false }));
      }
    }
    if (wSum > 0) setOverallScore(Math.round(total / wSum));
  };

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6">
      <div className="flex justify-between items-center border-b border-border pb-4">
        <div>
          <h2 className="font-display text-2xl font-bold">Posture Analysis Studio</h2>
          <p className="text-sm text-text-secondary">Upload up to 4 photos for a full-body posture scan powered by MediaPipe</p>
        </div>
        <button onClick={analyzeAll} disabled={!Object.keys(photos).length} className="btn-primary">
          <ScanFace size={15} /> Analyze Photos
        </button>
      </div>

      {overallScore != null && (
        <div className="card-glow p-6 flex items-center gap-8 animate-fade-in">
          <ScoreRing score={overallScore} size={110} strokeWidth={10} label="Overall Score" />
          <div className="flex-1 space-y-2">
            <h3 className="font-display text-xl font-semibold">{overallScore >= 80 ? "Excellent Posture" : "Room to Improve"}</h3>
            <p className="text-sm text-text-secondary">Landmarks evaluated across multiple vectors. Keep tracking your metrics monthly.</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {ANGLES.map((angle) => (
          <AngleSlot key={angle.key} angle={angle} file={photos[angle.key] || null} result={results[angle.key] || null} loading={!!loading[angle.key]} onDrop={handleDrop} onClear={handleClear} />
        ))}
      </div>
    </div>
  );
}
